const COPPER=1, SILVER=100, GOLD=10000, PLATINUM=1000000;
function toCoins(v){ const p=Math.floor(v/PLATINUM); v-=p*PLATINUM; const g=Math.floor(v/GOLD); v-=g*GOLD; const s=Math.floor(v/SILVER); v-=s*SILVER; return {p,g,s,c:v}; }
function formatCoins(v){
  const {p,g,s,c}=toCoins(Math.max(0,Math.round(v)));
  let parts=[]; if(p) parts.push(p+"P"); if(g) parts.push(g+"G"); if(s) parts.push(s+"S"); if(c || parts.length===0) parts.push(c+"C");
  return parts.join(" ");
}

